end

function OSManageOperateStatementDialog:Awake()
    self:AddUIClick()
    self:InitItemEnv()
    KTool.SetActive(self.GoodNode.gameObject,false)

    local isShow = true
    if not isNull(self.controller.Argument.parameters) and  not isNull(self.controller.Argument.parameters.isShow) then
        isShow = self.controller.Argument.parameters.isShow
    end
    KTool.SetActive(self.BtnDetail.gameObject,isShow)
end

function OSManageOperateStatementDialog:OnEventCloseRewardDialogListener()
    self:RemoveFlyCo()
    self.flyCo = {}
    for i, v in pairs(self.flyData) do
        self.flyCo[i] = GameUtils.StartFlyGoods(self.EffectStart,v.goodsId,v.isMore)
    end
end

function OSManageOperateStatementDialog:RemoveFlyCo()
    if not isNull(self.flyCo) then
        for i, v in pairs(self.flyCo) do
            if not isNull(v) then
                cs_coroutine.stop(v)
            end
        end
        self.flyCo = nil
    end
end

function OSManageOperateStatementDialog:InitItemEnv()
    self.goodItemEnv = {}
    for i = 1, MenuCount do
        local item = self["GoodItem"..i]
        if item then
            KTool.SetActive(item.gameObject,false)
            local env = CfUtils.GetLuaScr(item,ItemPath)
            if env then
               self.goodItemEnv[i] = env
            end
        end
    end
end

function OSManageOperateStatementDialog:AddUIClick()
    SetButtonAction(self.FontStyleButton.gameObject, Bind(self,self.OnFontBtnClick))
    SetButtonAction(self.BtnDetail.gameObject, Bind(self,self.OnBtnDetailClick))
end

