end

function OSManageOperateStatementDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            MaidCoffeeUtils.PlayMusicById(MaidCoffeeConstants.MaidCoffeeMusicName.OpenStatementDialog)
        end)
    end))
    return coWait
