function OSManageOperateStatementDialog:RequestShow()
    GameUtils.Request(Interfaces.MaidCoffeeMenuReport,{},function(request,response)
        if checkInt(response.errCode) == 0 then
            local data = response.data
            local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
            local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
            if maidCoffeeHomeDojo then
                maidCoffeeHomeDojo.reportTime = data.reportTime
                maidCoffeeHomeDojo.reportRewards = data.reportRewards
                self.offlineRewardNum = data.offlineRewardNum or 0
            end
            self:RefreshShowInfo()
        end
    end)
end

function OSManageOperateStatementDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self.parameters = self.controller.Argument.parameters
            self:RequestShow()
        end)
    end))
    return coWait
end

function OSManageOperateStatementDialog:RefreshShowInfo()
    self:SetItemShow()
    local isHaveReward = self:IsHaveReward()
    if isHaveReward then
        self:SetRewardShow()
    else
        local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
        local isHaveMenuSell = component:IsHaveMenuSell()
        local str = localize("当前没有套餐在售卖中哦")
        if isHaveMenuSell then
            str = localize("时间还早，再等等看吧")
        end
        CfUtils.FillText(self.TxtEmpty,str)
    end
    self:SetNodeStatus(isHaveReward)
    self:SetButtonShow(isHaveReward)
    self:SetDesShow()
end

function OSManageOperateStatementDialog:SetNodeStatus(state)
    KTool.SetActive(self.IncomeObtained.gameObject, state)
    KTool.SetActive(self.IncomeNone.gameObject,not state)
end

function OSManageOperateStatementDialog:SetItemShow()
    ---@type MaidCoffeeComponent
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    for i = 1, MenuCount do
        local _, isLock = component:GetIsLockedAndVolume(i)
        local data = {vo = MaidCoffeeUtils.GetMaidCoffeeMenuVo(i) , isLock = isLock }
        self.goodItemEnv[i]:RefreshUI(data,i)
    end
end

function OSManageOperateStatementDialog:SetDesShow()
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local cafeLevel = component:GetMaidCoffeeLevel()
    local vo = MaidCoffeeUtils.GetMaidCoffeeLevelExpVo(cafeLevel)
    local time = vo.time/60
    local addNum = vo.rewardNum
    local maxNum = vo.rewardNumMax
    local color = "<color=#9B9B9B>%s</color>"
    if self.offlineRewardNum >= maxNum then
        color = "<color=#F24BA9>%s</color>"
    end
    local _num3_ = string.format("(%s/%s)",string.format(color,self.offlineRewardNum),maxNum)
    local str = localize("每_num1_分钟固定收益_num2_新海币",{_num1_ = string.format("<color=#F24BA9>%s</color>",math.floor(time)),_num2_ = string.format("<color=#F24BA9>%s</color>",addNum)})
    CfUtils.FillText(self.TextDesc,str)
    CfUtils.FillText(self.TextNumber,_num3_)
end

function OSManageOperateStatementDialog:IsHaveReward()
    ---@type MaidCoffeeComponent
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    return component:IsHaveReward()
end

function OSManageOperateStatementDialog:SetRewardShow()
    ---@type MaidCoffeeComponent
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local showData = component:GetRewardData()
    local data = {}
    for i, v in pairs(showData) do
        if v.num > 0 then
            table.insert(data,v)
        end
    end
    self.flyData = {}
    for i = 1, #data do
        local go = GameObject.Instantiate(self.GoodNode.gameObject)
        if not isNull(go) then
            KTool.SetParent(go, self.Content.gameObject, false)
            CfUtils.RefeshGoodGo2(go,data[i].goodsId, data[i].num, nil, nil, function()
                local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(data[i].goodsId)
                GameUtils.ShowCommonTipsBoard(go, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
            end)
            local isRewardIn = self:IsRewardIn(data[i].goodsId)
            if isRewardIn then
                table.insert(self.flyData,{go = go,goodsId = data[i].goodsId,isMore = data[i].num >= MaidCoffeeConstants.IsMoreGoodsNum[data[i].goodsId]})
            end
            KTool.SetActive(go,true)
        end
    end
end

function OSManageOperateStatementDialog:IsRewardIn(id)
    local goodsId = self:GetTopGoodsId()
    for i, v in pairs(goodsId) do
        if checkNumber(v) == id then
            return true
        end
    end
    return false
end

function OSManageOperateStatementDialog:SetButtonShow(isHaveReward)
    local style = isHaveReward and "B3" or "B17"
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local isHaveMenuSell = component:IsHaveMenuSell()
    local str = localize("一键领取")
    if not isHaveReward and not isHaveMenuSell then
        style = "B3"
        str = localize("前往设置")
    end
    self.FontStyleButton:ResetFontStyle(style,str)
end

function OSManageOperateStatementDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
            self:RemoveFlyCo()
            self:Delete()
            if self.parameters and self.parameters.cb then
                self.parameters.cb()
            end
            self = nil --lua层的gc需要    
        end)
    end))
    return coWait
end

function OSManageOperateStatementDialog:__delete()
    self.goodItemEnv = nil
    self.controller = nil
end

---click----
function OSManageOperateStatementDialog:OnFontBtnClick()
    local isHaveReward = self:IsHaveReward()
    if isHaveReward then
        GameUtils.Request(Interfaces.MaidCoffeeMenuDrawSaleReward,{},function(request,response)
            if checkInt(response.errCode) == 0 then
                local pRewards = response.data.rewards
                if not isNull(pRewards) and #pRewards > 0 then
                    GoodsUtils.DrawRewards(pRewards, true)
                    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = pRewards,cb = function()
                        GameUtils.Request(Interfaces.MaidCoffeeMenuReport,{},function(request,response)
                            if checkInt(response.errCode) == 0 then
                                local data = response.data
                                local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
                                local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
                                self:OnEventCloseRewardDialogListener()
                                if maidCoffeeHomeDojo then
                                    maidCoffeeHomeDojo.reportTime = data.reportTime
                                    maidCoffeeHomeDojo.reportRewards = data.reportRewards
                                    self.offlineRewardNum = data.offlineRewardNum or 0
                                end
                                self:RefreshShowInfo()
                            end
                        end)
                    end } })
                end
            end
        end)
    else
        local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
        local isHaveMenuSell = component:IsHaveMenuSell()
        if not isHaveMenuSell then
            cs_coroutine.start(function()
                CS.Engine.UI.UIRaycastBlocker.Instance:AddCondition("OSManageOperateStatementDialog")
                UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeeMenuSettingDialog },{{ id = Constants.UITypeIds.UIMaidCoffeeManagerDialog}})
                coroutine.yield(CS.Engine.Lib.Yielders.GetWaitForSeconds(0.01))
                UIModule.CloseDialog(self.controller)
                CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("OSManageOperateStatementDialog")
            end)
        end
    end
end

function OSManageOperateStatementDialog:OnBtnDetailClick()
    UIModule.OpenDialog({ id = Constants.UITypeIds.MaidCoffeeReportDetails })
end

function OSManageOperateStatementDialog:GetTopGoodsId()
    if not isNull(self.topGoodsId) then
        return self.topGoodsId
    end
    self.topGoodsId = GameUtils.GetTopGoodsId(Constants.UITypeIds.UIMaidCoffeeStatementDialog)
    return self.topGoodsId
end

return OSManageOperateStatementDialog